  egg: ["....................", "........555.........", ".......54445........", "......5442245.......", ".....544222245......", ".....542332245......", "....54233322245.....", "....54223222245.....", "...5442222232245....", "...5422222333245....", "...5422222232245....", "...5433222222245....", "...5433322222445....", "....54422222445.....", "....55444444455.....", ".....555555555......", "......1111111......."],
  flag: ["....................", "........55..........", ".......545..........", ".......524666666....", ".......524777766....", ".......52466766.....", ".......5247666......", ".......52466666.....", ".......524666666....", ".......524..........", ".......524..........", ".......524..........", ".....5552455........", "....544444445.......", "..5552222222455.....", "..5333333333335.....", "..5555555555555....."],
